import discordfrom discord import Colorfrom discord.ext import commandsfrom utils.EmbedGeneratorUtil import EmbedGeneratorclass ReplyCommand(commands.Cog):    def __init__(self, bot: commands.Bot):        self.bot = bot    @commands.guild_only()    @commands.command(name="reply", help="Sends a simple reply to whatever is said")    async def reply(self, ctx: discord.ext.commands.Context):        """        Sends a simple reply to whatever is said.        :param ctx: This is the discord Interaction we can access data from        :return:        """        embed = EmbedGenerator(self.bot).generate_simple_message_embed(description="This is a reply to your message!", colour=Color.magenta(), timestamp=False)        await ctx.reply(embed=embed, mention_author=True)async def setup(bot: commands.Bot):    await bot.add_cog(ReplyCommand(bot))